class Solution {
    private int totalTilt = 0;

    public int findTilt(TreeNode root) {
        totalTilt = 0;
        subtreeSum(root);
        return totalTilt;
    }

    private int subtreeSum(TreeNode node) {
        if (node == null) {
            return 0;
        }

        int leftSum = subtreeSum(node.left);
        int rightSum = subtreeSum(node.right);
        totalTilt += Math.abs(leftSum - rightSum);
        return node.val + leftSum + rightSum;
    }
}

class Solution {
    public int findTilt(TreeNode root) {
        return solve(root)[1];
    }

    private int[] solve(TreeNode node) {
        if (node == null) {
            return new int[]{0, 0};
        }

        int[] left = solve(node.left);
        int[] right = solve(node.right);
        int subtreeSum = node.val + left[0] + right[0];
        int tiltTotal = left[1] + right[1] + Math.abs(left[0] - right[0]);
        return new int[]{subtreeSum, tiltTotal};
    }
}

class Solution {
    public int findTilt(TreeNode root) {
        if (root == null) {
            return 0;
        }

        java.util.ArrayDeque<TreeNode> stack = new java.util.ArrayDeque<>();
        java.util.ArrayDeque<TreeNode> postorder = new java.util.ArrayDeque<>();
        stack.push(root);

        while (!stack.isEmpty()) {
            TreeNode node = stack.pop();
            postorder.push(node);
            if (node.left != null) {
                stack.push(node.left);
            }
            if (node.right != null) {
                stack.push(node.right);
            }
        }

        java.util.HashMap<TreeNode, Integer> subtreeSums = new java.util.HashMap<>();
        int totalTilt = 0;
        while (!postorder.isEmpty()) {
            TreeNode node = postorder.pop();
            int leftSum = node.left == null ? 0 : subtreeSums.get(node.left);
            int rightSum = node.right == null ? 0 : subtreeSums.get(node.right);
            totalTilt += Math.abs(leftSum - rightSum);
            subtreeSums.put(node, node.val + leftSum + rightSum);
        }
        return totalTilt;
    }
}

class Solution {
    public int findTilt(TreeNode root) {
        if (root == null) {
            return 0;
        }

        java.util.ArrayDeque<TreeNode> nodeStack = new java.util.ArrayDeque<>();
        java.util.ArrayDeque<Boolean> visitedStack = new java.util.ArrayDeque<>();
        java.util.HashMap<TreeNode, Integer> subtreeSums = new java.util.HashMap<>();
        nodeStack.push(root);
        visitedStack.push(false);
        int totalTilt = 0;

        while (!nodeStack.isEmpty()) {
            TreeNode node = nodeStack.pop();
            boolean visited = visitedStack.pop();
            if (visited) {
                int leftSum = node.left == null ? 0 : subtreeSums.get(node.left);
                int rightSum = node.right == null ? 0 : subtreeSums.get(node.right);
                totalTilt += Math.abs(leftSum - rightSum);
                subtreeSums.put(node, node.val + leftSum + rightSum);
            } else {
                nodeStack.push(node);
                visitedStack.push(true);
                if (node.right != null) {
                    nodeStack.push(node.right);
                    visitedStack.push(false);
                }
                if (node.left != null) {
                    nodeStack.push(node.left);
                    visitedStack.push(false);
                }
            }
        }

        return totalTilt;
    }
}
